/bin/bash -lc "node --input-type=module <<'NODE'
const url = 'http://localhost:3210/'
const initial = await (await fetch(url)).text()
const id = initial.match(/\\"'$ACTION_ID_([a-f0-9]+)/)?.[1]
if (!id || !initial.includes('"'Notifications: <"'!-- -->Off'"')) throw new Error('Initial page or action missing')
let cookie = ''
for (const expected of ['on', 'off']) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Next-Action': id, 'Content-Type': 'text/plain;charset=UTF-8', ...(cookie && { Cookie: cookie }) },
    body: '[]',
    redirect: 'manual',
  })
  const body = await response.text()
  const setCookie = response.headers.get('set-cookie')
  if (response.status "'!== 200 || response.headers.has('"'location') || "'!setCookie?.includes(`notifications=${expected}`)) throw new Error(`Unexpected ${expected} action response: ${response.status} ${setCookie}`)
  cookie = `notifications=${expected}`
  const refreshed = await (await fetch(url, { headers: { Cookie: cookie } })).text()
  if (!refreshed.includes(`Notifications: <!-- -->${expected === '"'on' ? 'On' : 'Off'}"'`)) throw new Error(`Preference did not render ${expected}`)
  console.log(`Toggled ${expected}: status ${response.status}, no redirect, cookie persisted, response ${body.includes(expected === '"'on' ? 'On' : 'Off') ? 'includes' : 'does not include'} updated state"'`)
}
NODE'
